// ═══════════════════════════════════════════════════════
// Validate ApiCode — Module Chuyên Sâu AI (Schema_API_Metadata.sql)
// 10 ApiCode phân tích AI nâng cao
// ═══════════════════════════════════════════════════════
const body = $input.item.json.body || $input.item.json;
const headers = $('Webhook Nâng Cao').item.json.headers || {};

const VALID_API_CODES = [
  '@goi_y_don_hang',      // Gợi ý đơn hàng theo lịch sử KH
  '@upsell_goi_y',        // Upsell & gợi ý SP tăng giá trị đơn
  '@goi_y_don_thuoc',     // Tìm thuốc theo triệu chứng
  '@tuyen_ban_hang',      // Lịch tuyến bán hàng
  '@cham_diem_kh',        // Phân loại KH A/B/C
  '@tich_luy',            // Tích lũy chương trình KH
  '@san_pham_trong_tam',  // Sản phẩm trọng tâm đang chạy
  '@de_xuat_khuyen_mai',  // AI gợi ý xả hàng/combo
  '@tra_cuu_san_pham',    // Tra cứu giá & tồn kho tổng hợp
  '@import_trong_tam'     // [ADMIN] Import SP trọng tâm
];

const ApiCode = (body.ApiCode || '').trim().toLowerCase();
const username = body.username || 'default';
const token = headers.authorization || body.token || 'Bearer empty';

if (!ApiCode) {
  return [{ json: {
    loi: true,
    message: 'Thiếu ApiCode. Khối 4 chỉ xử lý phân tích AI chuyên sâu.',
    valid_codes: VALID_API_CODES
  }}];
}

if (!VALID_API_CODES.includes(ApiCode)) {
  return [{ json: {
    loi: true,
    message: `ApiCode "${ApiCode}" không thuộc Module Chuyên Sâu AI. Nếu là tra cứu cơ bản, hãy gọi hook-nghiepvu-crud.`,
    api_code_nhan: ApiCode,
    valid_codes: VALID_API_CODES
  }}];
}

// Map ApiCode → backend endpoint (từng module có SP riêng)
const SP_MAP = {
  '@goi_y_don_hang':     'API_GoiYDonHang_AI',
  '@upsell_goi_y':       'API_UpsellGoiY_AI',
  '@goi_y_don_thuoc':   'API_GoiYDonThuoc_AI',
  '@tuyen_ban_hang':     'API_TuyenBanHang_AI',
  '@cham_diem_kh':       'API_ChamDiemKH_AI',
  '@tich_luy':           'API_TichLuy_AI',
  '@san_pham_trong_tam': 'API_SanPhamTrongTam_AI',
  '@de_xuat_khuyen_mai': 'API_DeXuatKhuyenMai_AI',
  '@tra_cuu_san_pham':   'API_TraCuuSanPham_AI',
  '@import_trong_tam':   'API_SanPhamTrongTam_Import_AI'
};

return [{ json: {
  ApiCode,
  StoredProcedure: SP_MAP[ApiCode],
  username,
  token,
  hop_le: true,
  // Tham số phân tích AI
  ObjectID:      body.ObjectID      || null,
  SearchKey:     body.SearchKey     || null,
  TopN:          body.TopN          || null,
  Keyword:       body.Keyword       || null,
  NhomFilter:    body.NhomFilter    || null,
  SoNgayVangMat: body.SoNgayVangMat || null,
  ProgramID:     body.ProgramID     || null,
  FromDate:      body.FromDate      || null,
  ToDate:        body.ToDate        || null,
  ItemIDs:       body.ItemIDs       || null,
  JsonItems:     body.JsonItems     || null,
  JsonRules:     body.JsonRules     || null
}}];

const data = $input.item.json;
return [{ json: {
  ket_qua: data.message || 'ApiCode không hợp lệ cho Module Nâng Cao.',
  loi: true,
  goi_y: 'Nếu cần tra cứu cơ bản, hãy dùng Tool_NghiepVu_CoBan'
}}];

const data = $input.item.json;
const raw = data.data || data.result || data;
const ApiCode = data.ApiCode || '';

if (data.error || data.status === 'error') {
  return [{ json: {
    ket_qua: `❌ Lỗi phân tích ${ApiCode}: ${data.message || data.error}`,
    loi: true
  }}];
}

let ket_qua_text = '';

if (typeof raw === 'string') {
  ket_qua_text = raw;
} else if (Array.isArray(raw)) {
  ket_qua_text = raw.map((item, i) => {
    // Format thông minh tùy ApiCode
    if (item.TenSanPham || item.ItemName) {
      return `${i+1}. ${item.TenSanPham || item.ItemName} — SL gợi ý: ${item.SoLuongGoiY || item.TopN || 'N/A'}`;
    } else if (item.TenKhachHang || item.ObjectName) {
      return `${i+1}. ${item.TenKhachHang || item.ObjectName} — Nhóm: ${item.NhomKH || item.phan_loai || 'N/A'} — Điểm: ${item.Diem || item.Score || 'N/A'}`;
    } else if (item.NgayGheKe) {
      return `${i+1}. ${item.TenKhachHang || ''} — Vắng: ${item.SoNgayVang || '?'} ngày — ${item.DiaChi || ''}`;
    }
    return `${i+1}. ${JSON.stringify(item)}`;
  }).join('\n');
} else {
  ket_qua_text = JSON.stringify(raw, null, 2);
}

return [{ json: {
  ket_qua: ket_qua_text || 'Không có dữ liệu phân tích.',
  ApiCode: ApiCode,
  so_ban_ghi: Array.isArray(raw) ? raw.length : null
}}];
